    mapping(address => bool) public blacklists;
    mapping(address => mapping(TokenomicType => uint256)) public whitelists;
    mapping(TokenomicType => TokenomicSetting) private tokenomicSettings;

    //region - Events
    /////////////////////
    //      Ewents     //
